package com.personal.lld.simulator;
import com.personal.lld.domain.*; import com.personal.lld.repository.*; import com.personal.lld.service.*; import lombok.RequiredArgsConstructor; import lombok.extern.slf4j.Slf4j; import org.springframework.boot.CommandLineRunner; import org.springframework.stereotype.Component; import java.util.*;
@Component @RequiredArgsConstructor @Slf4j public class MusicStreamingSimulation implements CommandLineRunner {private final UserRepository users;private final SongRepository songs;private final ArtistRepository artists;private final AlbumRepository albums;private final SearchService search;private final PlaybackService playback;private final PlaylistService playlists;private final DownloadService downloads;private final RecommendationService recommendations; @Override public void run(String...args){seed();log.info("music_streaming_simulation started");User free=user("user1","user1@example.com","John Doe",SubscriptionTier.FREE);User premium=user("user2","user2@example.com","Jane Smith",SubscriptionTier.PREMIUM);var result=search.search("Love","SONG");log.info("search_completed query=Love songs_found={}",result.getSongs().size());if(result.getSongs().isEmpty())return;String song=result.getSongs().get(0).getSongId();var state=playback.play(free.getId(),PlaybackSource.SONG,song,null);log.info("playback_started session_id={} song={}",state.getSessionId(),state.getCurrentSong().getTitle());Playlist p=playlists.createPlaylist(free.getId(),"My Favorites",List.of(song));log.info("playlist_created playlist_id={} song_count={}",p.getPlaylistId(),p.getSongIds().size());Download d=downloads.download(premium.getId(),song,"device1");log.info("download_completed download_id={} status={}",d.getDownloadId(),d.getDownloadStatus());playback.updatePosition(state.getSessionId(),30);log.info("playback_position_updated session_id={} position=30",state.getSessionId());log.info("recommendations_returned count={}",recommendations.getRecommendations(free.getId()).size());log.info("music_streaming_simulation completed");}
 private User user(String username,String email,String name,SubscriptionTier tier){String id=UUID.randomUUID().toString();return users.save(new User(id,username,email,name,tier,System.currentTimeMillis()));} private void seed(){String aid=UUID.randomUUID().toString(),artistId="ART_"+aid.substring(0,8);artists.save(new Artist(aid,artistId,"The Beatles","https://example.com/beatles.jpg",System.currentTimeMillis()));String alid=UUID.randomUUID().toString(),albumId="ALB_"+alid.substring(0,8);albums.save(new Album(alid,albumId,"Abbey Road",artistId,"https://example.com/abbeyroad.jpg",System.currentTimeMillis()));for(int i=1;i<=5;i++){String id=UUID.randomUUID().toString(),sid="SONG_"+id.substring(0,8);songs.save(new Song(id,sid,"Love Song "+i,artistId,albumId,180+i*10,"Rock","https://example.com/audio/"+sid+".mp3","https://example.com/thumb/"+sid+".jpg",5000000L,AudioQuality.HIGH,AudioFormat.MP3,System.currentTimeMillis()));}}}
